def find_hole2(in_grid, out_grid, special, bg, copy_color, hole_vals):
    H=len(in_grid); W=len(in_grid[0])
    sp=[(r,c) for r in range(H) for c in range(W) if in_grid[r][c]==special]
    r0=min(r for r,c in sp); c0=min(c for r,c in sp)
    r1=max(r for r,c in sp); c1=max(r for r,c in sp)
    h=r1-r0+1; w=c1-c0+1
    tmpl=[]
    for dr in range(h):
        for dc in range(w):
            v=in_grid[r0+dr][c0+dc]
            if v==special: tmpl.append((dr,dc,'S'))
            else: tmpl.append((dr,dc,'H'))
    res=[]
    for r in range(H-h+1):
        for c in range(W-w+1):
            ok=True
            for dr,dc,t in tmpl:
                v=in_grid[r+dr][c+dc]
                if t=='S' and v!=copy_color: ok=False;break
                if t=='H' and v not in hole_vals: ok=False;break
            if ok: res.append((r,c))
    return tmpl, res

